# 2026-10-17 보정 : 행안부 공통표준 시험에서 미등록이던 단어(클레임·기획전·보험금·명세·입출고·신청인·의료진·요금제·교원·교과·학적·정정)를 표준단어로 교체. 옵션·장바구니·회선·단말은 업무 고유어로 유지(화면이 표준단어 신청 안내)
# 엔터티 = 표준단어 조합 + 엔터티 분류어(기본·상세·이력·내역·정보·관계·코드·집계·로그). 관계·속성·물리 권고는 엔터티 키(단어+분류어)로 참조, 생성 시 정합 검사
import json, io, sys
OUT = sys.argv[1]
def E(subj, words, clss, tp, desc): return {'subj': subj, 'words': words.split('+'), 'clss': clss or None, 'tp': tp, 'desc': desc}
def key(e): return ''.join(e['words']) + (e['clss'] or '')
T = {}
def ind(cd, nm, keywords, traits, subjects, ents, rels, attrs, phys):
    es = [E(*e) for e in ents]
    keys = {key(e) for e in es}
    assert len(keys) == len(es), cd
    for r in rels: assert r[0] in keys and r[1] in keys, (cd, r)
    for a in attrs: assert a[0] in keys, (cd, a)
    for p in phys: assert p[0] in keys, (cd, p)
    for e in es: assert e['subj'] in [s[0] for s in subjects], (cd, e)
    T[cd] = {
      'cd': cd, 'nm': nm, 'ver': '2026-10-17', 'status': '[확인중 : 마스터] 1차본',
      'keywords': keywords, 'traits': dict(zip(['biz', 'reg', 'data', 'volume'], traits)),
      'subjects': [{'nm': s[0], 'eng': s[1], 'abbr': s[2], 'desc': s[3]} for s in subjects],
      'entities': es,
      'rels': [{'prnt': r[0], 'chld': r[1], 'crdn': r[2], 'idnt': r[3], 'nm': r[4]} for r in rels],
      'attrs': [{'ent': a[0], 'terms': a[1], 'pk': a[2]} for a in attrs],
      'physical': [{'ent': p[0], 'kind': p[1], 'hint': p[2]} for p in phys],
    }

